actor Cache { func get() -> Int { 1 } }
@MainActor func show() async {
    let v = await Cache().get()  // actor hop
    print(v)
}
await show()

actor Counter { var n = 0 }
func bump(_ c: isolated Counter) { c.n += 1 }
let c = Counter()
await bump(c)
print(await c.n)

class Note { var text = "hi" }
actor Inbox {
    func take(_ n: sending Note) {
        print(n.text) }
}
await Inbox().take(Note())

